    m = len(grid[0])

    # Find non-zero color and bounding box
    color = None
    rows_nz = []
    cols_nz = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] != 0:
                color = grid[r][c]
                rows_nz.append(r)
                cols_nz.append(c)
    if color is None:
        return [row[:] for row in grid]

    r0, r1 = min(rows_nz), max(rows_nz)
    c0, c1 = min(cols_nz), max(cols_nz)

    # Build the bbox pattern, replacing hidden background with 5
    box = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            row.append(color if grid[r][c] != 0 else 5)
        box.append(row)

    # Heuristic period detection from rows/cols that contain multiple colored cells
    def detect_period(indices):
        if len(indices) < 2:
            return None
        diffs = []
        for i in range(1, len(indices)):
            d = indices[i] - indices[i - 1]
            if d > 1:
                diffs.append(d)
        if not diffs:
            return None
        counts = {}
        for d in diffs:
            counts[d] = counts.get(d, 0) + 1
        best = None
        best_count = -1
        for d in sorted(counts):
            if counts[d] > best_count:
                best_count = counts[d]
                best = d
        return best

    row_multi = [r for r in range(n) if sum(1 for v in grid[r] if v != 0) > 1]
    col_multi = []
    for c in range(m):
        cnt = 0
        for r in range(n):
            if grid[r][c] != 0:
                cnt += 1
        if cnt > 1:
            col_multi.append(c)

    pr = detect_period(row_multi)
    pc = detect_period(col_multi)

    if pr is None and pc is None:
        pr = pc = 1
    elif pr is None:
        pr = pc
    elif pc is None:
        pc = pr

    h = r1 - r0 + 1
    w = c1 - c0 + 1
    pr = max(1, min(pr, h))
    pc = max(1, min(pc, w))

    def map_row(r):
        if r < r0:
            return r0 + ((r - r0) % pr)
        if r > r1:
            return (r1 - pr + 1) + ((r - (r1 + 1)) % pr)
        return r

    def map_col(c):
        if c < c0:
            return c0 + ((c - c0) % pc)
        if c > c1:
            return (c1 - pc + 1) + ((c - (c1 + 1)) % pc)
        return c

    out = [[0] * m for _ in range(n)]
    for r in range(n):
        sr = map_row(r) - r0
        for c in range(m):
            sc = map_col(c) - c0
            out[r][c] = box[sr][sc]

    return out

